import{_ as t,o as i,c as a,a2 as s}from"./chunks/framework.5akMI7mQ.js";const u=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"ARCHITECTURE.md","filePath":"ARCHITECTURE.md","lastUpdated":1791201732000}'),n={name:"ARCHITECTURE.md"};function o(r,e,l,d,c,p){return i(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><h2 id="request-path" tabindex="-1">Request path <a class="header-anchor" href="#request-path" aria-label="Permalink to &quot;Request path&quot;">​</a></h2><p><code>HTTP gateway → scheduler → RuntimeBackend → Wasmtime component</code></p><ul><li><code>wednes-cli</code>: <code>wednesd</code> executable, direct component loading, registry deploy/run.</li><li><code>wednes-core</code>: request/response types, strict manifest validation, JSON file registry.</li><li><code>wednes-gateway</code>: Axum routes <code>/fn/:id</code> and <code>/fn/:id/*path</code>; global and per-function semaphore admission, rejecting saturation with HTTP 429.</li><li><code>wednes-runtime</code>: backend contract; <code>wednes-runtime-wasmtime</code>: compilation, typed export validation, per-invocation stores, WASI context, limits and epoch interruption.</li><li><code>wit/</code>: <code>wednes:function@0.1.0</code> contract; <code>sdk/rust</code> and <code>examples/</code>: guest-side bindings and examples.</li></ul><p>Each invocation uses fresh guest state; compiled components are reused within process. Linear-memory limits do not bound total host RSS, response copies, all allocations, or compiled code. Epoch interruption limits guest execution, not an end-to-end request deadline.</p><h2 id="registry-walkthrough" tabindex="-1">Registry walkthrough <a class="header-anchor" href="#registry-walkthrough" aria-label="Permalink to &quot;Registry walkthrough&quot;">​</a></h2><p>First complete README build steps. Keep manifest, component, and registry in same directory: deploy resolves artifact relative to manifest; run resolves it relative to registry. Artifact must be a basename, not a path. For reproducible hello setup:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/hello.toml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> target/hello.toml</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./target/release/wednesd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --manifest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> target/hello.toml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --registry</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> target/registry.json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./target/release/wednesd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --registry</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> target/registry.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --listen</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 127.0.0.1:8080</span></span></code></pre></div><p>In another terminal, POST to <code>http://127.0.0.1:8080/fn/hello</code> as in README. Stop with Ctrl-C. Deployment validates manifest, compiles component, checks typed ABI, then replaces registry metadata via rename. Existing metadata is retained if validation fails. This is not transactional artifact storage: do not modify deployed component files concurrently, and serialize deploy writers. Deployment does not copy artifacts into registry directory.</p><h2 id="current-boundaries" tabindex="-1">Current boundaries <a class="header-anchor" href="#current-boundaries" aria-label="Permalink to &quot;Current boundaries&quot;">​</a></h2><ul><li>No persistent deploy compilation cache. Deploy&#39;s compiled component dies with deploy process; run compiles/loads source again. Old M3 notes claiming managed persistent caching are superseded by this document.</li><li>No live reload: restart daemon to consume changed registry.</li><li>No control plane, distributed scheduler, authentication, TLS termination, billing, or durable guest state.</li><li>Environment, filesystem, and outbound HTTP enablement are unsupported; logging/clock capability configuration is rejected. Do not infer configurable capability enforcement from proposed fields.</li><li>Registry is trusted local metadata, not a concurrent multi-user database or a content-addressed artifact store.</li></ul><p>See <a href="./SECURITY">security</a> for trust boundaries and deployment precautions.</p>`,12)])])}const m=t(n,[["render",o]]);export{u as __pageData,m as default};
